  "implementation": "def solve(case):
    wti = case['word_token_indices']
    wl = case['word_labels']
    token_count = case['token_count']
    if len(wti) != len(wl):
        raise ValueError('Mismatch between number of word groups and word labels')
    token_labels = [0] * token_count  # placeholder; will set to 0 or 1
    # Use a sentinel like -1 to track unassigned tokens
    token_labels = [-1] * token_count
    seen = set()
    for idx, (indices, label) in enumerate(zip(wti, wl)):
        if not isinstance(indices, list):
            raise ValueError(f'word_token_indices[{idx}] is not a list')
        if not all(isinstance(i, int) for i in indices):
            raise ValueError(f'word_token_indices[{idx}] contains non-integer')
        if label not in (0, 1):
            raise ValueError(f'word_labels[{idx}] is not 0 or 1')
        for i in indices:
            if i < 0 or i >= token_count:
                raise ValueError(f'Token index {i} out of range [0, {token_count-1}]')
            if i in seen:
                raise ValueError(f'Duplicate token index {i}')
            seen.add(i)
            token_labels[i] = label
    if len(seen) != token_count:
        missing = [i for i in range(token_count) if token_labels[i] == -1]
        raise ValueError(f'Uncovered token indices: {missing}')
    kept_indices = [i for i, lbl in enumerate(token_labels) if lbl == 1]
    return {
        'kept_indices': kept_indices,
        'token_labels': token_labels
    }"
}
